    static void printLine(int[] v) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < v.length; i++) sb.append(v[i]).append(i + 1 < v.length ? " " : "");
        System.out.println(sb);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[][] edges = new int[n - 1][2];
        for (int i = 0; i < n - 1; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        int[][] res = analyze(n, edges);
        printLine(res[0]);
        if (res[1].length == 0) System.out.println(-1); else printLine(res[1]);
        printLine(res[2]);
    }
